<?php
namespace Tests\Feature;
use App\Models\{User,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableOptimisationRun as Run,TimetableStaffWindow as Window,TutorGroup,TimetableRoom as Room};
use App\Support\{CentrePlanning as P,TimetableOptimiser as O,ReviewedImports as H,TimetableGovernance as G};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use PHPUnit\Framework\Attributes\TestWith;
use Tests\Support\AuditFault;
use Tests\TestCase;
class TimetableNearbyDatesTest extends TestCase {
 use LazilyRefreshDatabase;
 private function publish(User $u,array $args):Plan{$p=P::save($u,1,null,0,(string)Str::uuid(),$args);P::check($u,1,$p,1,true);P::publish($u,1,$p->refresh(),2);return $p->refresh();}
 private function f(int $weeks=1,bool $dateOnly=false):array{
  $this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$staff=User::factory()->create(['role'=>'tutor']);$first='2026-11-16';$from=$first;$to=\Carbon\Carbon::parse($first)->addWeeks($weeks-1)->addDay()->toDateString();$dates=[];foreach(P::dates($first,$weeks)as$d){$dates[]=$d;$dates[]=\Carbon\Carbon::parse($d)->addDay()->toDateString();}P::windows($admin,1,$staff,$dates,H::hash(P::windowSource($staff,$dates)),true,'09:00','12:00');
  $base=['staff_id'=>$staff->id,'date'=>$first,'weeks'=>$weeks,'start'=>'09:00','end'=>'10:00','kind'=>'Admin','site'=>'Remote','room_id'=>null,'group_id'=>null,'headcount'=>null,'title'=>'Fictional fixed work51'];$fixed=$this->publish($admin,$base);$chosen=[...$base,'start'=>'11:00','end'=>'12:00','kind'=>'Preparation','title'=>'Fictional movable work51'];
  if($dateOnly){$room=Room::where('site','Doncaster')->firstOrFail();P::room($admin,1,$room,$room->version,['capacity'=>20,'uses'=>['Admin','Teaching'],'active'=>true]);$chosen=[...$chosen,'site'=>'Doncaster','room_id'=>$room->id];}
  $p=$this->publish($admin,$chosen);
  if($dateOnly){$other=User::factory()->create(['role'=>'tutor']);P::windows($admin,1,$other,$dates,H::hash(P::windowSource($other,$dates)),true,'09:00','12:00');$this->publish($admin,[...$chosen,'staff_id'=>$other->id,'start'=>'10:00','end'=>'11:00','title'=>'Fictional occupied room51']);}
  return compact('admin','staff','p','fixed','base','from','to','dates');
 }
 private function preview(array $f,int $flex=1):array{return O::preview($f['admin'],[$f['p']->id],$f['from'],$f['to'],false,$flex);}
 private function prepare(array $f,int $flex=1):Run{$v=$this->preview($f,$flex);$this->assertTrue($v['can_apply']);return O::prepare($f['admin'],1,[$f['p']->id],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'Fictional agreed arrangements51',$flex);}
 private function apply(array $f,Run $r):Run{return O::apply($f['admin'],1,$r,1,$r->details_hash,true);}
 private function reject(callable $fn):void{try{$fn();$this->fail('Expected a current-source validation hold');}catch(ValidationException){$this->addToAssertionCount(1);}}
 public function test_preview_is_read_only_and_binds_nearby_date_options():void{$f=$this->f();$v=$this->preview($f);$this->assertSame(1,$v['date_flex']);$this->assertSame(4,count($v['before']));$this->assertSame(1,$v['search']['options'][$f['p']->id]>0?1:0);$this->assertDatabaseCount('timetable_optimisation_runs',0);$this->assertDatabaseCount('timetable_plans',2);$this->assertFalse($v['search']['global_optimum_proved']);}
 public function test_same_date_improvement_is_preferred_when_equally_good():void{$f=$this->f();$v=$this->preview($f);$s=$v['suggestion'][$f['p']->id];$this->assertSame('2026-11-16',$s['after']['date']);$this->assertSame('10:00',$s['after']['start']);$this->assertSame(0,$v['after'][2]);}
 public function test_date_move_is_selected_and_applied_when_a_shared_room_prevents_same_day_improvement():void{
  $f=$this->f(1,true);$v=$this->preview($f);$s=$v['suggestion'][$f['p']->id];$this->assertSame(60,$v['before'][0]);$this->assertSame(0,$v['after'][0]);$this->assertSame('2026-11-17',$s['after']['date']);$this->assertSame('11:00',$s['after']['start']);$r=$this->apply($f,$this->prepare($f));$new=Plan::findOrFail($r->receipt['replacements'][$f['p']->id]);$this->assertSame('2026-11-17',$new->source['data']['args']['date']);$this->assertSame('Published',$new->state);$this->assertSame('Withdrawn',$f['p']->fresh()->state);$this->assertDatabaseCount('training_sessions',0);$this->assertDatabaseCount('learning_tasks',0);
 }
 public function test_repeated_date_move_shifts_every_occurrence_and_retains_the_weekly_pattern():void{
  $f=$this->f(2,true);$v=$this->preview($f);$s=$v['suggestion'][$f['p']->id];$this->assertSame(['2026-11-17','2026-11-24'],$s['proposed_dates']);$r=$this->apply($f,$this->prepare($f));$new=Plan::findOrFail($r->receipt['replacements'][$f['p']->id]);$this->assertSame(['2026-11-17','2026-11-24'],array_column($new->source['data']['rows'],'work_date'));$this->assertSame(2,$new->source['data']['args']['weeks']);
 }
 public function test_teaching_dates_stay_fixed_when_nearby_date_mode_is_selected():void{
  $f=$this->f();P::withdraw($f['admin'],1,$f['p'],$f['p']->version,'Fictional preparation replaced for teaching fixture');$room=Room::where('site','Doncaster')->firstOrFail();P::room($f['admin'],1,$room,$room->version,['capacity'=>20,'uses'=>['Teaching','Admin'],'active'=>true]);$group=TutorGroup::factory()->create(['tutor_id'=>$f['staff']->id,'active'=>true]);$f['p']=$this->publish($f['admin'],[...$f['base'],'kind'=>'Teaching','site'=>'Doncaster','room_id'=>$room->id,'group_id'=>$group->id,'headcount'=>20,'start'=>'11:00','end'=>'12:00']);$v=$this->preview($f);$this->assertSame(['2026-11-16'],$v['suggestion'][$f['p']->id]['proposed_dates']);$this->assertSame('2026-11-16',$v['suggestion'][$f['p']->id]['after']['date']);
 }
 public function test_linked_plan_and_uncertain_busy_source_still_hold_nearby_date_preview():void{
  $f=$this->f();$entry=Entry::where('plan_id',$f['p']->id)->firstOrFail();$entry->link_proof=['fictional'=>'linked'];$entry->save();$this->reject(fn()=>$this->preview($f));$entry->link_proof=null;$entry->save();\App\Models\TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'session_date'=>'2026-11-17','start_time'=>'bad']);$this->reject(fn()=>$this->preview($f));
 }
 public function test_alternative_window_change_invalidates_prepared_request():void{$f=$this->f();$r=$this->prepare($f);$date='2026-11-17';P::windows($f['admin'],1,$f['staff'],[$date],H::hash(P::windowSource($f['staff'],[$date])),false,null,null);$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['p']->fresh()->state);$this->assertSame('Prepared',$r->fresh()->state);}
 public function test_missing_alternative_windows_are_withheld_and_not_assumed_free():void{$f=$this->f();Window::where('user_id',$f['staff']->id)->whereDate('work_date','2026-11-17')->delete();$v=$this->preview($f);$this->assertNotEmpty($v['search']['issues']);$this->assertSame('2026-11-16',$v['suggestion'][$f['p']->id]['after']['date']);}
 public function test_changed_unknown_window_is_source_bound_too():void{$f=$this->f();Window::where('user_id',$f['staff']->id)->whereDate('work_date','2026-11-17')->delete();$r=$this->prepare($f);$date='2026-11-17';P::windows($f['admin'],1,$f['staff'],[$date],H::hash(P::windowSource($f['staff'],[$date])),true,'09:00','12:00');$this->reject(fn()=>$this->apply($f,$r));}
 public function test_corrupt_alternative_working_proof_is_withheld():void{$f=$this->f();DB::table('timetable_staff_windows')->where('user_id',$f['staff']->id)->whereDate('work_date','2026-11-17')->update(['start_time'=>'08:00']);$v=$this->preview($f);$this->assertNotEmpty($v['search']['issues']);$this->assertSame('2026-11-16',$v['suggestion'][$f['p']->id]['after']['date']);}
 public function test_all_weekly_occurrences_keep_duration_staff_and_weekly_cadence():void{$f=$this->f(2);$v=$this->preview($f);$s=$v['suggestion'][$f['p']->id];$this->assertSame(2,$s['occurrences']);$this->assertCount(2,$s['proposed_dates']);$this->assertSame(7,(int)\Carbon\Carbon::parse($s['proposed_dates'][0])->diffInDays(\Carbon\Carbon::parse($s['proposed_dates'][1])));foreach(['staff_id','room_id','group_id','kind','site','weeks','headcount','title']as$k)$this->assertSame($s['before'][$k],$s['after'][$k]);$this->assertSame(60,P::minutes($s['after']['end'])-P::minutes($s['after']['start']));}
 public function test_zero_mode_retains_the_existing_three_value_score():void{$f=$this->f();$v=$this->preview($f,0);$this->assertCount(3,$v['before']);$this->assertSame(0,$v['date_flex']);$this->assertSame($v['suggestion'][$f['p']->id]['dates'],$v['suggestion'][$f['p']->id]['proposed_dates']);}
 #[TestWith([-1])] #[TestWith([3])]
 public function test_date_radius_is_bounded(int $flex):void{$f=$this->f();$this->reject(fn()=>$this->preview($f,$flex));}
 public function test_fifth_plan_is_refused_in_nearby_date_mode():void{$f=$this->f();$ids=[$f['p']->id];for($i=0;$i<4;$i++)$ids[]=(string)Str::uuid();$this->reject(fn()=>O::preview($f['admin'],$ids,$f['from'],$f['to'],false,1));}
 public function test_preparation_does_not_move_work_and_exact_replay_creates_one_run():void{$f=$this->f();$v=$this->preview($f);$token=(string)Str::uuid();$a=O::prepare($f['admin'],1,[$f['p']->id],$f['from'],$f['to'],$v['source_hash'],$token,'Fictional exact request51',1);$b=O::prepare($f['admin'],1,[$f['p']->id],$f['from'],$f['to'],$v['source_hash'],$token,'Fictional exact request51',1);$this->assertSame($a->id,$b->id);$this->assertDatabaseCount('timetable_optimisation_runs',1);$this->assertDatabaseCount('timetable_plans',2);$this->assertSame('Published',$f['p']->fresh()->state);}
 public function test_radius_cannot_be_changed_on_a_preparation_replay():void{$f=$this->f();$v=$this->preview($f);$token=(string)Str::uuid();O::prepare($f['admin'],1,[$f['p']->id],$f['from'],$f['to'],$v['source_hash'],$token,'Fictional bound radius51',1);$this->reject(fn()=>O::prepare($f['admin'],1,[$f['p']->id],$f['from'],$f['to'],$v['source_hash'],$token,'Fictional bound radius51',0));}
 public function test_apply_is_atomic_and_does_not_change_tasks_attendance_or_staff_assignments():void{$f=$this->f();$r=$this->apply($f,$this->prepare($f));$this->assertSame('Applied',$r->state);$this->assertSame('Withdrawn',$f['p']->fresh()->state);$this->assertDatabaseCount('timetable_plans',3);foreach(['learning_tasks','training_sessions','attendance_marks','centre_manager_grants']as$t)$this->assertDatabaseCount($t,0);$this->assertSame('tutor',$f['staff']->fresh()->role);}
 public function test_applied_replay_is_exact_and_does_not_duplicate_reservations_or_audit():void{$f=$this->f();$r=$this->prepare($f);$first=$this->apply($f,$r);$events=DB::table('timetable_planning_events')->count();$again=$this->apply($f,$r);$this->assertSame($first->receipt,$again->receipt);$this->assertDatabaseCount('timetable_plans',3);$this->assertSame($events,DB::table('timetable_planning_events')->count());}
 public function test_final_audit_failure_rolls_back_withdrawal_and_replacements():void{$f=$this->f();$r=$this->prepare($f);AuditFault::install('nearby_final_fault','timetable_planning_events','fictional final audit failure','optimisation_applied');try{$this->apply($f,$r);$this->fail('Expected mandatory audit rollback');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Published',$f['p']->fresh()->state);$this->assertSame('Prepared',$r->fresh()->state);$this->assertDatabaseCount('timetable_plans',2);}
 public function test_expired_and_cancelled_proposals_cannot_apply():void{$f=$this->f();$r=$this->prepare($f);$this->travel(31)->minutes();$this->reject(fn()=>$this->apply($f,$r));O::cancel($f['admin'],1,$r,1,$r->details_hash);$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['p']->fresh()->state);}
 public function test_creator_auth_change_holds_apply():void{$f=$this->f();$r=$this->prepare($f);$f['admin']->auth_version=2;$f['admin']->save();$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$this->apply($f,$r);}
 public function test_ceo_pause_blocks_an_ordinary_planner_from_applying():void{$f=$this->f();$r=$this->prepare($f);$ceo=User::factory()->create(['role'=>'ceo']);G::pause($ceo,1,1,true,'Fictional pause51');$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$this->apply($f,$r);}
 public function test_http_preserves_the_selected_radius_through_preview_and_preparation():void{$f=$this->f();$v=$this->preview($f);$this->actingAs($f['admin'])->get('/centre-planning/optimiser')->assertOk()->assertSee('Allow one day either side');$this->post('/centre-planning/optimiser/preview',['from'=>$f['from'],'to'=>$f['to'],'plans'=>[$f['p']->id],'date_flex'=>1])->assertOk()->assertSee('name="date_flex" value="1"',false)->assertSee('Nearby-date mode');$this->post('/centre-planning/optimiser',['from'=>$f['from'],'to'=>$f['to'],'plans'=>[$f['p']->id],'date_flex'=>1,'source_hash'=>$v['source_hash'],'request_token'=>(string)Str::uuid(),'reason'=>'Fictional HTTP agreement51','confirmed'=>1])->assertRedirect();$this->assertSame(1,Run::first()->details['preview']['date_flex']);}
 public function test_http_refuses_an_unsupported_radius_and_ordinary_tutor():void{$f=$this->f();$this->actingAs($f['admin'])->postJson('/centre-planning/optimiser/preview',['from'=>$f['from'],'to'=>$f['to'],'plans'=>[$f['p']->id],'date_flex'=>9])->assertUnprocessable();$this->actingAs($f['staff'])->post('/centre-planning/optimiser/preview',['from'=>$f['from'],'to'=>$f['to'],'plans'=>[$f['p']->id],'date_flex'=>1])->assertForbidden();}
 public function test_release_check_does_not_claim_target_acceptance():void{$r=\App\Support\Release51Check::report();$this->assertSame('51',$r['pack']);$this->assertNotSame('needs_attention',$r['status']);$this->assertFalse($r['actual_target_acceptance']);$this->assertSame(0,$r['new_migrations']);$this->artisan('gta:release-check51')->assertSuccessful();}
}
